   CardPrinting[] selected={all.Single(c=>c.PrintingId=="fossil-en-unlimited1999"&&c.CollectorNumber=="1"),all.Single(c=>c.PrintingId=="fossil-en-unlimited1999"&&c.CollectorNumber=="16"),all.Single(c=>c.PrintingId=="jungle-en-unlimited1999"&&c.CollectorNumber=="1"),all.Single(c=>c.PrintingId=="jungle-en-unlimited1999"&&c.CollectorNumber=="17")};
   Need(selected[0].DisplayName=="Aerodactyl"&&selected[1].DisplayName=="Aerodactyl"&&selected[2].DisplayName=="Clefable"&&selected[3].DisplayName=="Clefable","Fixed canonical illustration comparison cards");cards=new CardEvidence[4];faces=new Texture2D[4];masks=new Texture2D[4];for(int n=0;n<4;n++){var c=selected[n];faces[n]=media.Adapter.CardFace(c.Id);masks[n]=media.Adapter.HoloMask(c.Id);var rect=new Rect(80+370*n,180,250,344);cards[n]=new CardEvidence{id=c.Id,name=c.DisplayName,collectorNumber=c.CollectorNumber,printingId=c.PrintingId,finish=c.Finish,hasMask=masks[n]!=null,maskWidth=masks[n]==null?0:masks[n].width,maskHeight=masks[n]==null?0:masks[n].height,faceWidth=faces[n].width,faceHeight=faces[n].height,rect=rect,conservativeDrawRect=TiltedSurfaceRenderer.ConservativeDrawRect(rect)};Need((n%2==0)==(c.Finish=="holo"),"Canonical selected finish");}
   phases=new[]{new Phase{filename="angle0-foil.png",yaw=0},new Phase{filename="angle0-matte.png",yaw=0,forceMatte=true},new Phase{filename="angle10-foil.png",yaw=10},new Phase{filename="angle10-matte.png",yaw=10,forceMatte=true}};surfaceRenderer=new TiltedSurfaceRenderer();game.ShuttingDown+=DisposeRenderer;
   CheckThat("passive-board-no-reward",game.GeneratedResultCount==0&&game.CurrentSession.Packs.Count==0,"No game view injection, pack generation, collection award or profile edit; diagnostic surfaceRenderer only");
   for(int n=0;n<4;n++){phaseIndex=n;int before=repaints;yield return Wait(()=>repaints>before,"actual shader board repaint",12);yield return new WaitForEndOfFrame();string path=Path.Combine(paths.ArtifactDirectory,phases[n].filename);ShoppingSmokePolicy.Ancestors(path);Need(!File.Exists(path),"Fresh screenshot only");ScreenCapture.CaptureScreenshot(path);var validator=typeof(Phase6ShoppingSmokeProbe).GetMethod("Png",BindingFlags.Static|BindingFlags.NonPublic);Need(validator!=null,"Existing PNG CRC/IEND validator");yield return Wait(()=>(bool)validator.Invoke(null,new object[]{path,1600,900}),"capture complete CRC/IEND",12);screenshots.Add(phases[n].filename);}
   CheckThat("four-complete-shader-captures",screenshots.Count==4,"Actual shader and fixed presentationClock=0; same-angle force-matte controls; external PNG pixel analysis still required");CheckThat("no-generation-after-captures",game.GeneratedResultCount==0&&game.CurrentSession.Packs.Count==0,"Session stays empty throughout passive rendering");completed=true;
  }
  void OnGUI(){if(!admitted||surfaceRenderer==null||phaseIndex<0||phaseIndex>=4||cards==null)return;GUI.depth=-32000;GUI.matrix=Matrix4x4.identity;GUI.color=Color.white;GUI.DrawTexture(new Rect(0,0,1600,900),Texture2D.blackTexture);GUI.Label(new Rect(80,55,1400,35),"Diagnostic rendering—not a pack/reward");var phase=phases[phaseIndex];GUI.Label(new Rect(80,95,1400,30),"Actual TiltedSurface shader • fixed clock 0 • yaw "+phase.yaw+" • "+(phase.forceMatte?"force MATTE control":"canonical finish"));bool drawn=true;for(int n=0;n<4;n++){var c=cards[n];GUI.Label(new Rect(c.rect.x,140,330,35),c.name+" #"+c.collectorNumber+" / "+c.finish);if(Event.current.type==EventType.Repaint)drawn&=surfaceRenderer.Draw(c.rect,faces[n],masks[n],!phase.forceMatte&&c.finish=="holo"?SurfaceFinish.Holo:SurfaceFinish.Matte,0,phase.yaw,0f);}if(Event.current.type==EventType.Repaint){if(!drawn){failure+="Actual shader Draw refused\n";}else repaints++;}}
